import { AxiosInstance, AxiosStatic } from 'axios';
import { EnhancedAxiosOptions, UserCountryAndLanguage, UserInfoToken } from './AuthenticationService.types';
interface AuthenticationService {
    getAuthHeader(): string | null;
    setAuthHeader(jwt: string): void;
    getRoles(): Array<string>;
    getRolesByPrefix(prefix: string): Array<string>;
    getZonesByRoles(prefix: string): Array<string>;
    hasRole(role: string): boolean;
    getUsername(): string;
    getLanguageByCountry(country: string): string;
    getUserCountryAndLanguage(): UserCountryAndLanguage;
    getUserEmailB2C(): string;
    getPreferredLanguageB2C(): string;
    getCountryB2C(): string;
    getRoleB2C(): string;
    getJWTExpiration(): string | null;
    refreshToken(token: string): Promise<AxiosStatic>;
    enhancedAxios(axiosInstance: AxiosInstance, options?: EnhancedAxiosOptions): AxiosInstance;
    getUserDistributionCenter(): Array<string>;
    getUserLanguage(): string;
    getUserCountry(): string;
    getIssuer(): string;
    needAcceptTheTerm(): Promise<boolean>;
    parseJwt(): UserInfoToken | null;
    getMaxTokenLifespan(): number;
    unsetLocalStorageKeys(keys: Array<string>): void;
    getSegmentation(): Array<string>;
    getUserId(): string;
    getUserFullNameB2C(): {
        given_name: string;
        family_name: string;
    };
    getSupportedCountries(): Array<string>;
    getVendorId(): string;
    getUserScopes(): Array<string>;
    getIsFederated(): boolean;
    getRefreshToken(): string | null;
    setRefreshToken(token: string): void;
    getUserRoleValue(prefix: string): string;
    isToplineUser(): boolean;
}
export default AuthenticationService;
